29	
30	      /* Color modes */
31	      --color-pink: #ff6b9d;
32	      --color-pink-rgb: 255, 107, 157;
33	      --color-teal: #4ecdc4;
34	      --color-teal-rgb: 78, 205, 196;
35	      --color-mint: #95e1d3;
36	      --color-mint-rgb: 149, 225, 211;
37	      --color-purple: #d946ef;
38	      --color-purple-rgb: 217, 70, 239;
39	      --color-orange: #ff9500;
40	      --color-orange-rgb: 255, 149, 0;
41	      --color-coral: #ff6b6b;
42	      --color-coral-rgb: 255, 107, 107;
43	      --color-cyan: #00d4ff;
44	      --color-cyan-rgb: 0, 212, 255;
45	    }
46	
47	    * {
48	      margin: 0;
49	      padding: 0;
50	      box-sizing: border-box;
51	    }
52	    html, body {
53	      height: 100%;
54	    }
55	    body {
56	      display: flex;
57	      flex-direction: column;
58	      justify-content: center;
59	      align-items: center;
60	      gap: 20px;
61	      background: linear-gradient(135deg, #5f6fd1 0%, #6b3fa0 100%);
62	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
63	      color: var(--color-white);
64	      font-size: 14px;
65	      padding: 20px;
66	    }
67	    .circle-container {
68	      cursor: pointer;
69	      border: none;
70	      background: none;
71	      padding: 0;
72	      position: relative;
73	      transition: transform var(--transition-normal), filter 0.2s ease;
74	      user-select: none;
75	      touch-action: manipulation;
76	      -webkit-tap-highlight-color: transparent;
77	      min-height: 44px;
78	      min-width: 44px;
79	      display: flex;
80	      align-items: center;
81	      justify-content: center;
82	    }
83	    .circle-container:focus {
84	      outline: none;
85	    }
86	    .circle-container:hover {
87	      transform: scale(1.05);
88	      filter: brightness(1.1);
89	    }
90	    .circle-container:active {
91	      transform: scale(0.98);
92	    }
93	    .circle-container:focus-visible {
94	      outline: 3px solid rgba(255, 255, 255, 0.95);
95	      outline-offset: 14px;
96	      border-radius: 50%;
97	      animation: focusRingPulse 0.4s ease-out;
98	    }
99	    svg {
100	      width: min(400px, 80vw);
101	      height: min(400px, 80vw);
102	      display: block;
103	      animation: fadeIn var(--transition-slow) ease-out, hintBounce 2.5s ease-in-out 0.8s 1 backwards;
104	      will-change: transform, opacity;
105	    }
106	    circle {
107	      fill: var(--color-white);
108	      stroke: rgba(255, 255, 255, 0.25);
109	      stroke-width: 1.5;
110	      animation: pulse var(--pulse-duration) ease-in-out infinite;
111	      filter: drop-shadow(0 20px 40px var(--shadow-color));
112	      transition: fill 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), r 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), stroke 0.4s ease, filter 0.4s ease;
113	      contain: paint;
114	    }
115	    .circle-container:is(:hover, :focus-visible) circle {
116	      fill: #e8f4f8;
117	      r: 205;
118	      stroke: rgba(255, 255, 255, 0.5);
119	      filter: drop-shadow(0 20px 50px rgba(255, 255, 255, 0.2));
120	    }
121	    .circle-container.active:not([class*="color-mode-"]) circle {
122	      fill: var(--color-gold);
123	      stroke: rgba(255, 215, 0, 0.4);
124	      animation: pulse-active 0.6s ease-in-out infinite;
125	      filter: drop-shadow(0 20px 50px rgba(255, 215, 0, 0.6));
126	      r: 200;
127	    }
128	
129	    .circle-container.color-mode-1 { --mode-color: var(--color-pink); --mode-rgb: var(--color-pink-rgb); }
130	    .circle-container.color-mode-2 { --mode-color: var(--color-teal); --mode-rgb: var(--color-teal-rgb); }
131	    .circle-container.color-mode-3 { --mode-color: var(--color-mint); --mode-rgb: var(--color-mint-rgb); }
132	    .circle-container.color-mode-4 { --mode-color: var(--color-purple); --mode-rgb: var(--color-purple-rgb); }
133	    .circle-container.color-mode-5 { --mode-color: var(--color-orange); --mode-rgb: var(--color-orange-rgb); }
134	    .circle-container.color-mode-6 { --mode-color: var(--color-coral); --mode-rgb: var(--color-coral-rgb); }
135	    .circle-container.color-mode-7 { --mode-color: var(--color-cyan); --mode-rgb: var(--color-cyan-rgb); }
136	
137	    [class*="color-mode-"] circle {
138	      fill: var(--mode-color);
139	      stroke: rgba(var(--mode-rgb), 0.4);
140	      filter: drop-shadow(0 20px 50px rgba(var(--mode-rgb), 0.45));
141	    }
142	    [class*="color-mode-"]:is(:hover, :focus-visible) circle {
