272	    }
273	    .circle-container.color-shifting circle {
274	      animation: colorShift var(--color-shift-duration) cubic-bezier(0.34, 1.56, 0.64, 1);
275	      opacity: 0.95;
276	    }
277	    .keyboard-hint {
278	      font-size: 11px;
279	      opacity: 0.85;
