569	<body>
570	  <button type="button" class="help-btn" id="help-btn" aria-label="Show keyboard shortcuts" title="Help (press ?)">?</button>
571	
572	  <div class="modal" id="help-modal" role="dialog" aria-labelledby="modal-header" aria-modal="true">
573	    <div class="modal-content">
574	      <button type="button" class="modal-close" id="modal-close" aria-label="Close help">✕</button>
575	      <div class="modal-header" id="modal-header">Keyboard Shortcuts</div>
576	      <div class="modal-shortcuts">
577	        <div class="shortcut-item">
578	          <span class="shortcut-key">C / →</span>
579	          <span class="shortcut-desc">Cycle to next color</span>
580	        </div>
581	        <div class="shortcut-item">
582	          <span class="shortcut-key">←</span>
