613	  <main>
614	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-expanded="false" aria-describedby="hint-text">
615	      <svg viewBox="0 0 400 400" preserveAspectRatio="xMidYMid meet" aria-hidden="true" role="presentation">
616	        <circle cx="200" cy="200" r="200"/>
617	      </svg>
618	    </button>
619	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
620	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
621	    <div class="controls" role="group" aria-label="Circle controls">
622	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
623	      <button type="button" class="control-btn" id="random-btn" aria-label="Jump to random color">Random</button>
624	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
625	    </div>
626	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> or <kbd>→</kbd> to cycle • <kbd>X</kbd> for random • <kbd>R</kbd> to reset • <kbd>?</kbd> for help</div>
627	  </main>
628	
629	  <script defer>
630	    (() => {
631	      const COLORS = [
632	        { class: 'default', name: 'Default White' },
633	        { class: 'color-mode-1', name: 'Pink' },
634	        { class: 'color-mode-2', name: 'Teal' },
635	        { class: 'color-mode-3', name: 'Mint' },
636	        { class: 'color-mode-4', name: 'Purple' },
637	        { class: 'color-mode-5', name: 'Orange' },
638	        { class: 'color-mode-6', name: 'Coral' },
639	        { class: 'color-mode-7', name: 'Cyan' }
640	      ];
641	
642	      const getRandomColorMode = () => Math.floor(Math.random() * COLORS.length);
643	      const isTouch = (() => {
644	        if (!window.matchMedia) return false;
645	        const hasCoarsePointer = window.matchMedia('(pointer:coarse)').matches;
646	        const hasTouchEvents = 'ontouchstart' in window;
647	        const hasMaxTouchPoints = (navigator.maxTouchPoints ?? 0) > 0;
648	        return hasCoarsePointer || hasTouchEvents || hasMaxTouchPoints;
649	      })();
650	
651	      const CONFIG = {
652	        storageKey: 'circle-state',
653	        tapDelay: 300,
654	        colorShiftDuration: 500,
655	        saveDebounceDuration: 100,
656	        keyDebounce: 50,
657	        isTouch
658	      };
659	
660	      const el = {
661	        circle: document.getElementById('decorative-circle'),
662	        hint: document.getElementById('hint-text'),
663	        modeIndicator: document.getElementById('mode-indicator'),
664	        cycleBtn: document.getElementById('cycle-btn'),
665	        randomBtn: document.getElementById('random-btn'),
666	        resetBtn: document.getElementById('reset-btn'),
667	        helpBtn: document.getElementById('help-btn'),
668	        helpModal: document.getElementById('help-modal'),
669	        modalClose: document.getElementById('modal-close')
670	      };
671	
672	      let state = { active: false, colorMode: 0 };
673	      let tapCount = 0;
674	      let tapTimeout = null;
675	      let animatingColorShift = false;
676	      let saveTimeout = null;
677	      let lastKeyTime = 0;
678	
679	      const haptic = (duration) => navigator.vibrate?.(duration);
680	
681	      const getColorClass = (mode) => COLORS[mode % COLORS.length]?.class || '';
682	      const getColorName = (mode) => COLORS[mode % COLORS.length]?.name || '';
683	
684	      const storage = {
685	        save() {
686	          clearTimeout(saveTimeout);
687	          saveTimeout = setTimeout(() => {
688	            try {
689	              if (typeof localStorage !== 'undefined') {
690	                localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
691	              }
692	            } catch (e) {
693	              // Storage error (quota exceeded or unavailable)
694	            }
695	          }, CONFIG.saveDebounceDuration);
696	        },
697	        load() {
698	          try {
699	            if (typeof localStorage !== 'undefined') {
700	              const saved = localStorage.getItem(CONFIG.storageKey);
701	              if (saved) {
702	                const parsed = JSON.parse(saved);
703	                if (parsed && typeof parsed === 'object' &&
704	                    typeof parsed.active === 'boolean' &&
705	                    typeof parsed.colorMode === 'number') {
706	                  state = parsed;
707	                }
708	              }
709	            }
710	          } catch (e) {
711	            // Use default state on parse error
712	          }
713	        }
714	      };
715	
716	      const updateClasses = () => {
717	        if (!el.circle) return;
718	
719	        el.circle.classList.toggle('active', state.active);
720	        el.circle.setAttribute('aria-pressed', state.active.toString());
721	        el.circle.setAttribute('aria-expanded', (state.colorMode > 0).toString());
722	
723	        const oldColorClass = Array.from(el.circle.classList).find(cls => cls.startsWith('color-mode-'));
724	        const newColorClass = getColorClass(state.colorMode);
725	
726	        if (oldColorClass !== newColorClass) {
727	          if (oldColorClass) {
728	            el.circle.classList.remove(oldColorClass);
729	          }
730	          if (newColorClass !== 'default') {
731	            el.circle.classList.add(newColorClass);
732	          }
733	        }
734	      };
735	
736	      const updateUI = () => {
737	        const isActive = state.active;
738	        const hint = isTouch
739	          ? (isActive ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle')
740	          : (isActive ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle');
741	        el.hint.textContent = hint;
742	
743	        const showMode = isActive && state.colorMode > 0;
744	        el.modeIndicator.classList.toggle('visible', showMode);
745	        if (showMode) {
746	          const colorName = getColorName(state.colorMode).toUpperCase();
747	          el.modeIndicator.textContent = `◆ ${colorName}`;
748	          el.modeIndicator.setAttribute('aria-label', `Color: ${colorName}`);
749	        }
750	      };
751	
752	      const applyState = () => {
753	        updateClasses();
754	        updateUI();
755	      };
756	
757	      const modal = {
758	        previousFocus: null,
759	        open() {
760	          if (!el.helpModal || !el.modalClose) return;
761	          modal.previousFocus = document.activeElement;
762	          el.helpModal.classList.add('active');
763	          setTimeout(() => el.modalClose.focus(), 0);
764	          document.body.style.overflow = 'hidden';
765	        },
766	        close() {
767	          if (!el.helpModal) return;
768	          el.helpModal.classList.remove('active');
769	          document.body.style.overflow = '';
770	          setTimeout(() => {
771	            if (modal.previousFocus && typeof modal.previousFocus.focus === 'function') {
772	              modal.previousFocus.focus();
773	            }
774	          }, 0);
775	        }
776	      };
777	
778	      const toggleActive = () => {
779	        state.active = !state.active;
780	        haptic(10);
781	        applyState();
782	        storage.save();
783	      };
784	
785	      const changeColor = (newMode, hapticPattern = 20) => {
786	        if (animatingColorShift || !el.circle) return;
787	        const currentMode = state.colorMode;
788	        if (currentMode === newMode) return;
789	
790	        animatingColorShift = true;
791	        state.colorMode = newMode;
792	        state.active = true;
793	        haptic(hapticPattern);
794	        el.circle.classList.add('color-shifting');
795	        const animTimeout = setTimeout(() => {
796	          el.circle?.classList.remove('color-shifting');
797	          animatingColorShift = false;
798	        }, CONFIG.colorShiftDuration);
799	        applyState();
800	        storage.save();
801	      };
802	
803	      const cycleColor = () => changeColor((state.colorMode + 1) % COLORS.length);
804	      const cycleColorReverse = () => changeColor((state.colorMode - 1 + COLORS.length) % COLORS.length);
805	      const randomizeColor = () => changeColor(getRandomColorMode(), [20, 10, 20]);
806	
807	      const resetState = () => {
808	        state = { active: false, colorMode: 0 };
809	        haptic(10);
810	        applyState();
811	        storage.save();
812	      };
813	
814	      const handleTouchEnd = () => {
815	        tapCount++;
816	        haptic(12);
817	        clearTimeout(tapTimeout);
818	
819	        if (tapCount === 1) {
820	          tapTimeout = setTimeout(() => {
821	            if (tapCount === 1) {
822	              toggleActive();
823	            }
824	            tapCount = 0;
825	          }, CONFIG.tapDelay);
826	        } else if (tapCount >= 2) {
827	          tapCount = 0;
828	          cycleColor();
829	        }
830	      };
831	
832	      const keyHandlers = {
833	        ' ': toggleActive,
834	        'enter': toggleActive,
835	        'escape': resetState,
836	        'c': cycleColor,
837	        'x': randomizeColor,
838	        'r': resetState,
839	        '?': modal.open,
840	        'arrowright': cycleColor,
841	        'arrowleft': cycleColorReverse
842	      };
843	
844	      const handleKeyDown = (e) => {
845	        const key = e.key.toLowerCase();
846	        const handler = keyHandlers[key];
847	        if (!handler) return;
848	
849	        const now = Date.now();
850	        if (now - lastKeyTime < CONFIG.keyDebounce) return;
851	
852	        e.preventDefault();
853	        handler();
854	        lastKeyTime = now;
855	      };
856	
857	      const handleModalKeyDown = (e) => {
858	        if (!el.helpModal?.classList.contains('active')) return;
859	
860	        if (e.key === 'Escape') {
861	          e.preventDefault();
862	          modal.close();
863	          return;
864	        }
865	
866	        if (e.key === 'Tab') {
867	          const focusableSelector = 'button:not([disabled]), [tabindex]:not([disabled])';
868	          const focusableElements = Array.from(el.helpModal.querySelectorAll(focusableSelector));
869	          if (focusableElements.length === 0) return;
870	
871	          const firstElement = focusableElements[0];
872	          const lastElement = focusableElements[focusableElements.length - 1];
873	          const activeElement = document.activeElement;
874	
875	          if (e.shiftKey && activeElement === firstElement) {
876	            e.preventDefault();
877	            lastElement.focus();
878	          } else if (!e.shiftKey && activeElement === lastElement) {
879	            e.preventDefault();
880	            firstElement.focus();
881	          }
882	        }
883	      };
884	
885	      const handleModalBackdropClick = (e) => {
886	        if (e.target === el.helpModal) {
887	          modal.close();
888	        }
889	      };
890	
891	      const initListeners = () => {
892	        if (!el.circle) return;
893	
894	        el.circle.addEventListener('blur', () => {
895	          tapCount = 0;
896	          clearTimeout(tapTimeout);
897	        }, { passive: true });
898	
899	        if (isTouch) {
900	          el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
901	          if (window.PointerEvent) {
902	            el.circle.addEventListener('pointerup', handleTouchEnd, { passive: true });
903	          }
904	        } else {
905	          el.circle.addEventListener('click', toggleActive, { passive: true });
906	          el.circle.addEventListener('dblclick', cycleColor, { passive: true });
907	        }
908	
909	        document.addEventListener('keydown', handleKeyDown);
910	
911	        el.cycleBtn?.addEventListener('click', cycleColor, { passive: true });
912	        el.randomBtn?.addEventListener('click', randomizeColor, { passive: true });
913	        el.resetBtn?.addEventListener('click', resetState, { passive: true });
914	        el.helpBtn?.addEventListener('click', modal.open, { passive: true });
915	        el.modalClose?.addEventListener('click', modal.close, { passive: true });
916	        el.helpModal?.addEventListener('click', handleModalBackdropClick, { passive: true });
917	        el.helpModal?.addEventListener('keydown', handleModalKeyDown);
918	      };
919	
920	      const initApp = () => {
921	        if (!el.circle) return;
922	        storage.load();
923	        applyState();
924	        initListeners();
925	      };
926	
927	      const ensureSave = () => {
928	        clearTimeout(saveTimeout);
929	        clearTimeout(tapTimeout);
930	        try {
931	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
932	        } catch (e) {
933	          // Silently fail on storage errors during page hide
934	        }
935	      };
936	
937	      if (document.readyState === 'loading') {
938	        document.addEventListener('DOMContentLoaded', initApp);
939	      } else {
940	        initApp();
941	      }
942	
943	      window.addEventListener('pagehide', ensureSave);
944	      window.addEventListener('beforeunload', ensureSave);
945	    })();
946	  </script>
947	</body>
